<script setup>
import { ref } from 'vue'
import VariableInsert from './VariableInsert.vue'
const props=defineProps({draft:{type:Object,required:true},fields:{type:Array,default:()=>[]}})
const latitudeInput=ref(null),longitudeInput=ref(null),nameInput=ref(null),addressInput=ref(null)
function insert(prop,token,el){const input=el?.value,value=String(props.draft[prop]||''),start=input?.selectionStart??value.length,end=input?.selectionEnd??start;props.draft[prop]=value.slice(0,start)+token+value.slice(end);setTimeout(()=>{if(input){const p=start+token.length;input.focus();input.setSelectionRange(p,p)}},0)}
</script>
<template><section class="location-editor"><div class="info"><b>Native location message</b><span>Latitude and longitude are sent as a real map location on both WhatsApp and Telegram. Variables such as <code>%latitude%</code> and <code>%longitude%</code> are supported.</span></div><label>Latitude *<input ref="latitudeInput" v-model="draft.latitude" placeholder="e.g. -26.12035"><VariableInsert :fields="fields" @insert="token=>insert('latitude',token,latitudeInput)"/></label><label>Longitude *<input ref="longitudeInput" v-model="draft.longitude" placeholder="e.g. 28.369038"><VariableInsert :fields="fields" @insert="token=>insert('longitude',token,longitudeInput)"/></label><label>Location name <input ref="nameInput" v-model="draft.location_name" placeholder="Optional — WhatsApp displays this with the pin"><VariableInsert :fields="fields" @insert="token=>insert('location_name',token,nameInput)"/><small>WhatsApp supports the name directly. Telegram sends the native map pin using the coordinates.</small></label><label>Address <textarea ref="addressInput" v-model="draft.address" rows="3" placeholder="Optional address"></textarea><VariableInsert :fields="fields" @insert="token=>insert('address',token,addressInput)"/><small>Used by WhatsApp when supplied.</small></label></section></template>
<style scoped>.location-editor{display:flex;flex-direction:column}.info{padding:12px 13px;margin-bottom:15px;border:1px solid #cfe8dc;border-radius:9px;background:#f2faf6}.info b,.info span{display:block}.info b{font-size:12px;color:#167348}.info span{margin-top:4px;font-size:11px;line-height:1.5;color:#71847b}.info code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;color:#176a43}.location-editor label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700;margin-bottom:14px}.location-editor input,.location-editor textarea{border:1px solid #d7e1dd;border-radius:8px;padding:10px;font:inherit}.location-editor small{font-weight:400;color:#7c8b85;line-height:1.4}</style>